local services = {"auth","checkout","payments","search"}
local overview = {}
for _, s in ipairs(services) do
  local r = tool('search_logs', { service = s, level = 'ERROR', page = 1 })
  overview[#overview + 1] = {
    service = s,
    total_errors = r.total_items,
    total_pages = r.total_pages,
    first_ts = r.items[1] and r.items[1].ts or nil,
    last_ts = r.items[#r.items] and r.items[#r.items].ts or nil
  }
end
return overview

local services = {"auth","checkout","payments","search"}
local overview = {}
for _, s in ipairs(services) do
  local r = tool('search_logs', { service = s, level = 'ERROR', page = 1 })
  overview[#overview + 1] = {
    service = s,
    total_errors = r.total_items,
    total_pages = r.total_pages,
    first_ts = r.items[1] and r.items[1].ts or nil,
    last_ts = r.items[#r.items] and r.items[#r.items].ts or nil
  }
end
return overview

local errs = {}
for page = 1, 2 do
  local r = tool('search_logs', { service = 'payments', level = 'ERROR', page = page })
  for _, it in ipairs(r.items) do
    errs[#errs + 1] = { ts = it.ts, msg = it.message }
  end
end
local deploys = tool('get_deploys', { service = 'payments' })
return { errors = errs, deploys = deploys }
